comment on table public.voto_apuracao_contagem is 'Contagem agregada por urna física, pergunta e opção (ou branco/nulo) lançada pelo apurador. Não liga voto a pessoa. [lgpd:nenhum]';
comment on column public.voto_apuracao_contagem.tipo is 'opcao, branco ou nulo.';
